[InitializeOnLoad]public static class GridShiftV10Checks {
 static GridShiftV10Checks(){EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("GS.V10.Test",false)){SessionState.SetBool("GS.V10.Test",false);var go=new GameObject("V10Checks");Object.DontDestroyOnLoad(go);go.AddComponent<GridShiftV10Runner>();}};}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Prepare(){if(!SessionState.GetBool("GS.V10.Test",false))return;DeliverySaveStore.OverridePath=Path.GetFullPath("Temp/v10-test-save.json");GridShiftControls.Prefix="GS.V10.Tests.Keys.";GridShiftControls.Reset();GridShiftTutorial.Prefix="GS.V10.Tests.Tutorial.";GridShiftTutorial.Skip();}
 public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/MainMenu.unity");SessionState.SetBool("GS.V10.Test",true);EditorApplication.isPlaying=true;}
}
public sealed class GridShiftV10Runner:MonoBehaviour {
 readonly StringBuilder report=new StringBuilder();readonly List<string> errors=new List<string>();Keyboard keyboard;readonly List<InputDevice> disabled=new List<InputDevice>();
 void Check(bool ok,string label){report.AppendLine((ok?"PASS ":"FAIL ")+label);File.WriteAllText("Docs/Validacao10/progress.txt",report.ToString());if(!ok)throw new Exception(label);}
 void Log(string text,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception)errors.Add(text);}
 void Current(){keyboard.MakeCurrent();}
 void Loaded(Scene scene,LoadSceneMode mode){foreach(var root in scene.GetRootGameObjects())foreach(var w in root.GetComponentsInChildren<ClimaReal>(true))w.enabled=false;}
 IEnumerator Start(){Application.runInBackground=true;Application.logMessageReceived+=Log;SceneManager.sceneLoaded+=Loaded;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;foreach(var d in InputSystem.devices.ToArray())if(d is Keyboard){InputSystem.DisableDevice(d);disabled.Add(d);}keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.onAfterUpdate+=Current;var stack=new Stack<IEnumerator>();stack.Push(Run());bool success=true;while(stack.Count>0){bool more;object value=null;try{more=stack.Peek().MoveNext();if(more)value=stack.Peek().Current;}catch(Exception e){success=false;report.AppendLine("FAIL "+e);break;}if(!more){stack.Pop();continue;}if(value is IEnumerator nested&&!(value is CustomYieldInstruction)){stack.Push(nested);continue;}yield return value;}Time.timeScale=1;InputSystem.onAfterUpdate-=Current;InputSystem.RemoveDevice(keyboard);foreach(var d in disabled)if(d.added)InputSystem.EnableDevice(d);Application.logMessageReceived-=Log;SceneManager.sceneLoaded-=Loaded;success&=errors.Count==0;report.AppendLine("ERRORS "+string.Join("; ",errors));report.AppendLine("RESULT "+(success?"SUCCESS":"FAILURE"));File.WriteAllText("Docs/Validacao10/runtime.txt",report.ToString());GridShiftControls.Prefix="GS.Keys.";GridShiftControls.Reload();GridShiftTutorial.Prefix="GS.Tutorial.";DeliverySaveStore.OverridePath=null;EditorApplication.isPlaying=false;}
 IEnumerator Until(Func<bool> test,float seconds,string label){float until=Time.realtimeSinceStartup+seconds;while(!test()&&Time.realtimeSinceStartup<until)yield return null;Check(test(),label);}
 IEnumerator Tap(Key key){InputSystem.QueueStateEvent(keyboard,new KeyboardState(key));yield return null;yield return null;InputSystem.QueueStateEvent(keyboard,new KeyboardState());yield return null;yield return null;}
 UnityEngine.UI.Button Button(Transform root,string label)=>root.GetComponentsInChildren<UnityEngine.UI.Button>(true).First(b=>b.name==label);
 IEnumerator Run(){yield return new WaitForSecondsRealtime(4);var menu=Object.FindFirstObjectByType<GridShiftMainMenu>();Check(menu!=null,"menu principal existente carregado");menu.StartGame(false);yield return Until(()=>GridShiftCampaignUI.ModalOpen,60,"nova partida apresenta introdução");Button(GridShiftCampaignUI.Instance.transform,"Pular introdução / Começar").onClick.Invoke();yield return Until(()=>WorldSession.Instance!=null&&!WorldSession.Instance.Busy&&SceneManager.GetActiveScene().name=="Office",60,"pular introdução termina dentro do Office");var manager=DeliveryManager.Instance;var company=manager.Company;Check(company.Ready&&company.State.introSeen&&company.State.reputation==25,"campanha inicializada e introdução persistida");Check(Mathf.Abs(manager.Money-company.Balance.startingCash)<.01f,"capital inicial usa o único saldo existente");yield return Until(()=>manager.fleet.Count>=3,30,"frota existente adotada sem duplicar veículos");yield return Tap(Key.G);var office=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="Office");var tablet=office.GetComponent<PortableTablet>();yield return Until(()=>tablet.IsOpen&&!tablet.Animating,8,"G abre tablet no Office");Check(company.Missions.First.step==1,"abertura real do tablet avança missão");Check(company.Missions.ReadOpportunity(out _),"mensagem comercial pode ser lida");yield return Tap(Key.Escape);yield return Until(()=>!tablet.IsOpen&&!tablet.Animating,8,"ESC guarda tablet sem abrir pausa");Check(!PauseMenu.Instance.IsOpen&&!office.ControlsBlocked,"tablet restaura controles");var managerId=manager.GetInstanceID();WorldSession.Instance.RequestTransition("SampleScene",office.transform);yield return Until(()=>!WorldSession.Instance.Busy&&SceneManager.GetActiveScene().name=="SampleScene",60,"saída real do Office preserva cidade");yield return Until(()=>company.Missions.First.step==3,5,"objetivo muda para encontrar Carlos");var merchant=Object.FindFirstObjectByType<GridShiftMerchant>();Check(merchant!=null,"NPC Carlos usa prefab do projeto");var player=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).First(p=>p.gameObject.scene.name=="SampleScene");var cc=player.GetComponent<CharacterController>();cc.enabled=false;player.transform.position=merchant.transform.position+merchant.transform.forward*1.3f;cc.enabled=true;yield return null;yield return Tap(Key.E);Check(GridShiftCampaignUI.ModalOpen&&player.ControlsBlocked,"E próximo ao NPC abre diálogo com foco");GridShiftV10Capture.Save("npc-dialogue",player.CameraTransform.GetComponent<Camera>());Button(GridShiftCampaignUI.Instance.transform,"Consultar detalhes").onClick.Invoke();Button(GridShiftCampaignUI.Instance.transform,"Aceitar proposta").onClick.Invoke();Check(!GridShiftCampaignUI.ModalOpen&&company.Missions.First.step==6&&!player.ControlsBlocked,"aceitar proposta avança objetivo e restaura controle");company.Missions.VisitOperations();var pickup=manager.Point(company.State.merchantPoint);var car=manager.fleet.First(v=>v.kind==FleetKind.Car&&v.Available&&DeliveryRouting.Find(v.driver.RotaAtual,pickup.route,DeliveryRouting.Behind(v.driver,pickup))!=null);float fuelBefore=company.Health(car.id).fuel;Check(company.Missions.StartContract(car.id,out var error),"escolha de veículo inicia entrega física: "+error);var order=manager.orders.First(o=>o.id==company.Missions.First.orderId);GridShiftOperationsUI.Instance.Open("map");yield return new WaitForSecondsRealtime(.3f);Check(company.Missions.First.step==10,"mapa real avança acompanhamento da missão");GridShiftV10Capture.Save("mission-map",player.CameraTransform.GetComponent<Camera>());GridShiftOperationsUI.Instance.Close();float before=manager.Money;Time.timeScale=6;yield return Until(()=>order.status==DeliveryStatus.Completed,300,"primeiro contrato concluído pelo veículo real");Time.timeScale=1;yield return Until(()=>company.Missions.First.step==11,5,"conclusão física libera confirmação");Check(company.Health(car.id).fuel<fuelBefore&&company.Health(car.id).meters>1,"circulação real consome combustível e acumula distância");float delivered=manager.Money;manager.Complete(order);Check(Mathf.Abs(manager.Money-delivered)<.01f,"recompensa de entrega não duplica");Check(company.Missions.Claim("first-contract",out error),"confirmar missão paga bônus: "+error);float claimed=manager.Money;Check(!company.Missions.Claim("first-contract",out _)&&Mathf.Abs(manager.Money-claimed)<.01f,"bônus da missão é recebido uma única vez");Check(company.State.reputation==32,"reputação sobe por entrega e missão, sem aumento por tempo");Check(manager.GetInstanceID()==managerId,"transição preserva o mesmo gerenciador de entregas");
 var bill=company.State.bills.First();float cash=manager.Money;Check(company.Finance.Pay(bill.id,out error),"pagar cobrança real: "+error);Check(Mathf.Abs(manager.Money-(cash-bill.amount-bill.lateFee))<.02f,"pagamento desconta o saldo existente");cash=manager.Money;Check(!company.Finance.Pay(bill.id,out _)&&manager.Money==cash,"pagamento duplicado recusado");Check(company.Employee("rui",true,out error)&&company.Mechanic,"contratar mecânico aplica benefício real");int employees=company.Employees;WorldSession.Instance.RestoreCalendar(7.01);company.Finance.Tick();Check(company.State.closedWeeks==1&&company.State.weeks.Count==1,"fechamento semanal emitido pelo calendário");int bills=company.State.bills.Count;company.Finance.Tick();Check(company.State.bills.Count==bills&&company.State.weeks.Count==1,"repetir fechamento não duplica despesas nem relatório");Check(company.State.bills.Any(b=>b.category=="Salários"&&b.amount>0),"salários são cobrados no fechamento correto");Check(company.Employee("rui",false,out error)&&company.Employees==employees-1&&!company.Mechanic,"desligar funcionário atualiza contagem e benefício");var h=company.Health(car.id);float f=h.fuel,w=h.condition;for(int i=0;i<100;i++)company.Distance(car,10);Check(h.fuel<f&&h.condition<w,"modelo de consumo e desgaste depende de distância");Check(company.Service(car.id,false,out error)&&h.fuel==100,"abastecimento cobra e restaura tanque");Check(company.Service(car.id,true,out error)&&!car.Available,"manutenção cobra e torna veículo indisponível");var route=car.driver.RotaAtual;WorldSession.Instance.RestoreCalendar(company.Day+.18);company.Finance.Tick();Check(h.condition==100&&h.maintenanceUntil==0&&car.driver.RotaAtual!=null,"manutenção termina e preserva rota válida");var unpaid=company.State.bills.First(b=>!b.paid);WorldSession.Instance.RestoreCalendar(unpaid.dueDay+1);company.Finance.Tick();float fee=unpaid.lateFee;int rep=company.State.reputation;company.Finance.Tick();Check(fee>0&&unpaid.lateFee==fee&&company.State.reputation==rep,"multa e reputação por atraso são aplicadas uma vez");company.Missions.Tick();Check(company.EventOffer()!=null&&manager.Offers().Any(o=>o.id==company.EventOffer().id),"evento de demanda cria contrato real disponível");
 DeliverySaveData save=null;Check(manager.GetComponent<DeliveryPersistence>().Save()&&DeliverySaveStore.Read(out save),"save v2 guarda estado completo validado");float savedMoney=manager.Money;int savedBills=company.State.bills.Count,savedEmployees=company.Employees;string savedMission=company.Missions.First.orderId;DeliverySaveStore.Pending=save;yield return SceneManager.LoadSceneAsync("SampleScene",LoadSceneMode.Single);yield return new WaitForSecondsRealtime(3);manager=DeliveryManager.Instance;company=manager.Company;Check(company.Ready&&Mathf.Abs(manager.Money-savedMoney)<.01f&&company.State.bills.Count==savedBills&&company.Employees==savedEmployees,"recarregar preserva dinheiro, contas e funcionários");Check(company.State.introSeen&&company.Missions.First.rewardClaimed&&company.Missions.First.orderId==savedMission&&!GridShiftCampaignUI.ModalOpen,"carregar não repete introdução ou recompensa");Check(!company.Missions.Claim("first-contract",out _)&&manager.Money==savedMoney,"recompensa permanece única depois de carregar");var old=new DeliverySaveData{version=1,money=50,orders=new List<DeliveryOrder>()};Check(DeliverySaveStore.Write(old)&&DeliverySaveStore.Read(out var legacy)&&legacy.version==1,"save anterior v1 continua legível");Check(manager.GetComponent<DeliveryPersistence>().Save(),"teste final restaura save v2");
 }
